# ---------- claude_usage/domain.py ----------

"""Core types shared by every layer. No I/O here."""


import hashlib
import time
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Protocol, Tuple


class Clock(Protocol):
    def now(self) -> float: ...


class SystemClock:
    def now(self) -> float:
        return time.time()


# Providers: the coding agents whose limits are shown.
CLAUDE, CODEX, AGY = "claude", "codex", "agy"
PROVIDERS = (CLAUDE, CODEX, AGY)  # menu order
PROVIDER_NAMES = {CLAUDE: "Claude Code", CODEX: "Codex", AGY: "Antigravity"}

# Window kinds every provider shares. Anything else is shown under its own name.
FIVE_HOUR, WEEKLY = "5h", "7d"
FIVE_HOUR_SECONDS, WEEK_SECONDS = 5 * 3600, 7 * 86400


@dataclass(frozen=True)
class Window:
    """One limit: percent used of a rolling window.

    kind: FIVE_HOUR, WEEKLY, or the provider's own word for another cadence.
    pct: None when the plan has no such limit (a verified Claude Ultra has no 5-hour limit).
    reset: epoch seconds, 0 when unknown. seconds: window length, 0 when unknown.
    name: the model or model group the limit covers, e.g. "Fable"; "" for the whole plan.
    """
    kind: str
    pct: Optional[float]
    reset: int = 0
    seconds: int = 0
    name: str = ""

    def to_dict(self) -> Dict[str, Any]:
        return {"kind": self.kind, "pct": self.pct, "reset": self.reset,
                "seconds": self.seconds, "name": self.name}

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> Window:
        pct = d.get("pct")
        return cls(str(d["kind"]), None if pct is None else float(pct), int(d.get("reset") or 0),
                   int(d.get("seconds") or 0), str(d.get("name") or ""))


@dataclass(frozen=True)
class Usage:
    """Plan usage of one account: its windows in display order, plus what the provider says
    about the account itself (plan name, email), "" when it says nothing."""
    windows: Tuple[Window, ...]
    plan: str = ""
    email: str = ""

    def percentages(self) -> List[Optional[float]]:
        """Each window's %, None for a limit the plan does not have."""
        return [w.pct for w in self.windows]

    def to_dict(self) -> Dict[str, Any]:
        return {"windows": [w.to_dict() for w in self.windows], "plan": self.plan,
                "email": self.email}

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> Usage:
        return cls(tuple(Window.from_dict(w) for w in d["windows"]), str(d.get("plan") or ""),
                   str(d.get("email") or ""))


class LoginExpired(Exception):
    """A browser login whose access token has expired; only Claude Code can renew it."""


class Account(ABC):
    """One identity of one provider whose limits can be read."""

    provider = CLAUDE
    #: True for a Claude browser login (it has a profile email), False otherwise.
    is_login = False

    def __init__(self, label: str):
        self.label = label

    @property
    @abstractmethod
    def identity(self) -> str:
        """Stable key within the provider: equal identities are the same account."""

    @property
    def cache_key(self) -> str:
        # Claude keys stay unprefixed, so its caches survive the upgrade.
        key = self.identity if self.provider == CLAUDE else self.provider + ":" + self.identity
        return hashlib.sha256(key.encode()).hexdigest()[:16]


class ClaudeAccount(Account):
    """A Claude Code identity, read with its OAuth access token."""

    @abstractmethod
    def token(self) -> str:
        """The OAuth access token. May raise (locked keychain, expired login...)."""


class TokenAccount(ClaudeAccount):
    """A `claude setup-token` token found in a shell file, the environment or the conf file."""

    def __init__(self, label: str, token: str):
        super().__init__(label)
        self._token = token

    @property
    def identity(self) -> str:
        return self._token

    def token(self) -> str:
        return self._token


class AccountSource(Protocol):
    """Finds accounts of one kind (keychain, credentials file, shell files...)."""

    def accounts(self) -> List[Account]: ...


class UsageReader(Protocol):
    """Reads the current usage of the accounts of one provider. Raises when it cannot."""

    def read(self, account: Account) -> Usage: ...


@dataclass(frozen=True)
class AccountRow:
    """Everything the menu shows for one account."""
    short: str
    label: str
    detail: str
    usage: Optional[Usage]
    error: Optional[str]
    provider: str = CLAUDE


# ---------- claude_usage/infra.py ----------

"""Small I/O adapters: HTTP client, JSON file cache, installed command-line tools."""


import glob
import json
import os
import queue
import shutil
import signal
import subprocess
import tempfile
import threading
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from typing import Any, Dict, List, Mapping, Optional, Protocol, Sequence, Tuple


@dataclass
class HttpResponse:
    status: int
    headers: Dict[str, str] = field(default_factory=dict)  # lower-case names
    body: bytes = b""

    def json(self) -> Any:
        return json.loads(self.body.decode("utf-8"))


class HttpClient(Protocol):
    def request(self, url: str, method: str = "GET", headers: Optional[Dict[str, str]] = None,
                body: Optional[bytes] = None, timeout: float = 15) -> HttpResponse: ...


class UrllibHttpClient:
    """HttpClient over urllib. An HTTP error status is a response, not an exception;
    network failures still raise (URLError, timeout)."""

    def request(self, url: str, method: str = "GET", headers: Optional[Dict[str, str]] = None,
                body: Optional[bytes] = None, timeout: float = 15) -> HttpResponse:
        req = urllib.request.Request(url, data=body, headers=headers or {}, method=method)
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return HttpResponse(r.status, _lower_headers(r.headers), r.read())
        except urllib.error.HTTPError as e:
            return HttpResponse(e.code, _lower_headers(e.headers), e.read() or b"")


def _lower_headers(headers) -> Dict[str, str]:
    return {k.lower(): v for k, v in headers.items()} if headers else {}


class JsonCache:
    """Named JSON documents in one directory, with their age."""

    def __init__(self, directory: str, clock: Clock):
        self.directory = directory
        self._clock = clock

    def path(self, name: str) -> str:
        return os.path.join(self.directory, name + ".json")

    def load(self, name: str) -> Any:
        try:
            with open(self.path(name), encoding="utf-8") as f:
                return json.load(f)
        except (OSError, ValueError):
            return None

    def save(self, name: str, data: Any) -> bool:
        """Best effort: a cache that cannot be written (full disk, a concurrent writer, a file
        held open on Windows) must never break the menu. Returns False when nothing was saved."""
        tmp = None
        try:
            os.makedirs(self.directory, exist_ok=True)
            fd, tmp = tempfile.mkstemp(prefix=name + ".", suffix=".tmp", dir=self.directory)
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(data, f)
            os.replace(tmp, self.path(name))
            return True
        except OSError:
            if tmp:
                try:
                    os.remove(tmp)
                except OSError:
                    pass
            return False

    def age(self, name: str) -> float:
        try:
            return self._clock.now() - os.path.getmtime(self.path(name))
        except OSError:
            return float("inf")

    def fresh(self, name: str, max_age: float) -> Any:
        """The document if it is younger than max_age seconds, else None."""
        return self.load(name) if self.age(name) < max_age else None


# ---------- command-line tools (codex, agy) ----------

# SwiftBar, Argos and a login-started tray run with a minimal PATH, so the usual install
# folders are searched first. They also come before the shell PATH, where wrapper shims of
# terminal apps may shadow the real tool.
POSIX_CLI_DIRS = (".local/bin", "bin", ".npm-global/bin", ".bun/bin", ".volta/bin", ".cargo/bin",
                  "/opt/homebrew/bin", "/usr/local/bin", "/usr/bin", "/bin")
WINDOWS_CLI_DIRS = (r"%APPDATA%\npm", r"%LOCALAPPDATA%\Microsoft\WinGet\Links",
                    r"%LOCALAPPDATA%\Programs\bin", r"~\.local\bin", r"~\bin")
# No console window flashing up from the Windows tray on every refresh.
NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0)


def cli_search_path(home: str, env: Mapping[str, str], windows: bool) -> str:
    """The PATH to find and run command-line tools with: install folders, then env PATH."""
    if windows:
        dirs = [os.path.expandvars(d).replace("~", home, 1) for d in WINDOWS_CLI_DIRS]
    else:
        dirs = [d if d.startswith("/") else os.path.join(home, d) for d in POSIX_CLI_DIRS]
        dirs += node_manager_dirs(home)
    dirs += (env.get("PATH") or "").split(os.pathsep)
    seen: List[str] = []
    for d in dirs:
        if d and "%" not in d and d not in seen:
            seen.append(d)
    return os.pathsep.join(seen)


def node_manager_dirs(home: str) -> List[str]:
    """bin folders of nvm (newest Node first) and fnm's default Node, where `npm i -g`
    puts tools such as codex; a login shell adds them to PATH, SwiftBar does not."""
    nvm = glob.glob(os.path.join(home, ".nvm", "versions", "node", "*", "bin"))
    nvm.sort(key=os.path.getmtime, reverse=True)
    fnm = [os.path.join(home, d, "fnm", "aliases", "default", "bin")
           for d in (".local/share", "Library/Application Support")]
    return nvm + fnm


def kill_tree(proc: subprocess.Popen) -> None:
    """Kill a started tool and every process it started. A launcher (an npm .cmd shim, a shell
    wrapper) may fork the real program, which would otherwise keep running and hold our pipes
    open, so a read on them never ends."""
    try:
        if os.name == "nt":
            subprocess.run(["taskkill", "/T", "/F", "/PID", str(proc.pid)], capture_output=True,
                           timeout=10, creationflags=NO_WINDOW)
        else:
            os.killpg(proc.pid, signal.SIGKILL)  # start() made it a process group leader
    except (OSError, subprocess.SubprocessError):
        pass
    try:
        proc.kill()
    except OSError:
        pass


class LineReader:
    """The stdout lines of a started tool, read on a daemon thread so a stuck tool cannot
    block the caller past its deadline."""

    def __init__(self, stream):
        self._lines: queue.Queue = queue.Queue()
        threading.Thread(target=self._pump, args=(stream,), daemon=True).start()

    def _pump(self, stream) -> None:
        try:
            for line in iter(stream.readline, ""):
                self._lines.put(line)
        except (OSError, ValueError):
            pass
        self._lines.put("")  # end of output

    def readline(self, timeout: float) -> str:
        """The next line, "" at the end of output; raises TimeoutError after timeout seconds."""
        try:
            return self._lines.get(timeout=max(0.0, timeout))
        except queue.Empty:
            raise TimeoutError from None


@dataclass(frozen=True)
class Cli:
    """An installed command-line tool. argv: the command that starts it, e.g. ("/x/codex",),
    or (python, "fake_codex.py") in tests. env: the environment it runs in."""
    argv: Tuple[str, ...]
    env: Mapping[str, str]

    def run(self, args: Sequence[str], timeout: float) -> subprocess.CompletedProcess:
        """Run to completion; raises subprocess.TimeoutExpired (after killing the whole
        process tree) or OSError."""
        proc = self._popen(args, subprocess.DEVNULL, subprocess.PIPE)
        try:
            out, err = proc.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            kill_tree(proc)
            try:
                proc.communicate(timeout=2)
            except subprocess.SubprocessError:
                pass
            raise
        return subprocess.CompletedProcess(proc.args, proc.returncode, out, err)

    def start(self, args: Sequence[str]) -> subprocess.Popen:
        """Start with line-buffered text pipes on stdin and stdout, for a JSON-RPC session.
        Stop it with kill_tree, not Popen.kill."""
        return self._popen(args, subprocess.PIPE, subprocess.DEVNULL)

    def _popen(self, args: Sequence[str], stdin: int, stderr: int) -> subprocess.Popen:
        # POSIX: its own session (and process group), so kill_tree reaches its children.
        return subprocess.Popen(list(self.argv) + list(args), env=dict(self.env), stdin=stdin,
                                stdout=subprocess.PIPE, stderr=stderr, text=True,
                                encoding="utf-8", errors="replace", bufsize=1,
                                creationflags=NO_WINDOW, start_new_session=os.name != "nt")


class CliLocator:
    """Finds installed tools on cli_search_path and runs them with that PATH."""

    def __init__(self, home: str, env: Mapping[str, str], windows: bool):
        self._path = cli_search_path(home, env, windows)
        self._env = dict(env, PATH=self._path)

    def find(self, name: str) -> Optional[Cli]:
        found = shutil.which(name, path=self._path)
        return Cli((found,), self._env) if found else None


# ---------- claude_usage/antigravity.py ----------

"""Google Antigravity CLI (`agy`): limits from its read-only `/usage` print-mode command.

`agy -p /usage --output-format json` runs no agent turn and spends no quota. It reports groups
of models, each with buckets (a window, the fraction still available and when it resets).
"""


import json
import os
import re
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Tuple


AGY_DAY = "1d"
AGY_DAY_SECONDS = 86400
AGY_ERROR_MAX = 160
AGY_STATE_DIR = os.path.join(".gemini", "antigravity-cli")
_AGY_TIME = re.compile(r"^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d):(\d\d)(?:\.\d+)?"
                       r"(?:(Z)|([+-])(\d\d):?(\d\d))?$", re.IGNORECASE)


class AgyAccount(Account):
    """The one account agy is signed in to on this machine."""

    provider = AGY

    def __init__(self):
        super().__init__("agy")

    @property
    def identity(self) -> str:
        return "agy"


class AgySource:
    """agy is installed and has been run on this machine, so it has a state folder."""

    def __init__(self, home: str, cli: Optional[Cli]):
        self._state_dir = os.path.join(home, AGY_STATE_DIR)
        self._cli = cli

    def accounts(self) -> List[Account]:
        if self._cli is not None and os.path.isdir(self._state_dir):
            return [AgyAccount()]
        return []


def _agy_epoch(text: Any) -> int:
    """ISO-8601 to epoch seconds; 0 when absent or unparsable. No zone means UTC."""
    m = _AGY_TIME.match(text.strip()) if isinstance(text, str) else None
    if not m:
        return 0
    year, month, day, hour, minute, second = (int(g) for g in m.groups()[:6])
    offset = timedelta(0)
    if m.group(8):
        offset = timedelta(hours=int(m.group(9)), minutes=int(m.group(10)))
        if m.group(8) == "-":
            offset = -offset
    try:
        moment = datetime(year, month, day, hour, minute, second, tzinfo=timezone(offset))
    except ValueError:
        return 0
    return int(moment.timestamp())


def _agy_window_kind(window: Any) -> Tuple[str, int]:
    """(kind, seconds) of a bucket's window word, e.g. "weekly", "five_hour", "5h", "daily"."""
    word = str(window or "")
    norm = re.sub(r"[^a-z0-9]", "", word.lower())
    if "week" in norm:
        return WEEKLY, WEEK_SECONDS
    if "five" in norm or "5h" in norm or ("5" in norm and "hour" in norm):
        return FIVE_HOUR, FIVE_HOUR_SECONDS
    if "daily" in norm or norm == "day":
        return AGY_DAY, AGY_DAY_SECONDS
    return word, 0


def _agy_group_name(name: Any) -> str:
    """"Gemini Models" -> "Gemini", "Claude and GPT models" -> "Claude + GPT"."""
    short = re.sub(r"\s+models?\s*$", "", str(name or "").strip(), flags=re.IGNORECASE)
    return re.sub(r"\s+and\s+", " + ", short, flags=re.IGNORECASE)


def _agy_fraction(bucket: Dict[str, Any]) -> Optional[float]:
    value = bucket.get("remaining_fraction")
    if isinstance(value, bool) or not isinstance(value, (int, float)) or value != value:
        return None
    return float(value)


def _agy_windows(group: Dict[str, Any]) -> List[Window]:
    name = _agy_group_name(group.get("name"))
    found = []
    for bucket in group.get("buckets") or []:
        if not isinstance(bucket, dict):
            continue
        fraction = _agy_fraction(bucket)
        if fraction is None:
            continue  # no data is never shown as 0 percent
        kind, seconds = _agy_window_kind(bucket.get("window"))
        pct = round(min(100.0, max(0.0, (1 - fraction) * 100)), 2)
        found.append(Window(kind, pct, _agy_epoch(bucket.get("reset_time")), seconds, name))
    return sorted(found, key=lambda w: w.seconds or float("inf"))


def _agy_json(stdout: str) -> Optional[Dict[str, Any]]:
    """The last stdout line that is a JSON object, else the whole output."""
    for text in reversed([ln.strip() for ln in stdout.splitlines()] + [stdout.strip()]):
        if text.startswith("{"):
            try:
                parsed = json.loads(text)
            except ValueError:
                continue
            if isinstance(parsed, dict):
                return parsed
    return None


class AgyReader:
    """Reads agy's limits through `agy -p /usage`, logging to our own file so that polling
    does not rotate the user's own agy logs away."""

    def __init__(self, cli: Cli, log_path: str, timeout: float = 30):
        self._cli = cli
        self._log_path = log_path
        self._timeout = timeout

    def read(self, account: Account) -> Usage:
        os.makedirs(os.path.dirname(os.path.abspath(self._log_path)), exist_ok=True)
        # agy appends to --log-file; emptying it first keeps only the last run, for diagnosis.
        open(self._log_path, "w").close()
        done = self._cli.run(["-p", "/usage", "--output-format", "json",
                              "--log-file", self._log_path], self._timeout)
        reply = _agy_json(done.stdout or "")
        if reply is None:
            raise RuntimeError("agy exited with code %s" % done.returncode)
        if reply.get("status") != "SUCCESS":
            text = str(reply.get("error") or "").strip()
            raise RuntimeError(text[:AGY_ERROR_MAX] or "agy exited with code %s" % done.returncode)
        command = reply.get("command")
        data = command.get("data") if isinstance(command, dict) else None
        groups = data.get("groups") if isinstance(data, dict) else None
        windows = [w for g in groups or [] if isinstance(g, dict) for w in _agy_windows(g)]
        if not windows:
            raise RuntimeError("no Antigravity limits")
        return Usage(tuple(windows))


